"""
pi_agent/tools/registry.py

Dynamic tool registry. Built-in tools are always present.
Skill tools and extension tools are registered/deregistered at runtime.
"""

import sys
import traceback
from typing import Any

from langchain_core.tools import BaseTool
from loguru import logger

from .builtin import BUILTIN_TOOLS


class ToolRegistry:
    """
    Manages the agent's active toolset.

    Built-in tools (read/write/edit/bash) are always present.
    Skill and extension tools can be added/removed dynamically.
    """

    def __init__(self) -> None:
        self._tools: dict[str, BaseTool] = {}
        self._source_map: dict[str, str] = {}  # tool_name → source (builtin/skill/extension)

        # Register built-in tools
        for t in BUILTIN_TOOLS:
            self._tools[t.name] = t
            self._source_map[t.name] = "builtin"

    def register(self, tool: BaseTool, source: str = "extension") -> None:
        """Register a new tool. source: 'skill:name' | 'extension:name' | 'builtin'"""
        try:
            if tool.name in self._tools:
                logger.warning(
                    "Tool '{}' already registered from '{}'. Overwriting with '{}'.",
                    tool.name,
                    self._source_map.get(tool.name),
                    source,
                )
            self._tools[tool.name] = tool
            self._source_map[tool.name] = source
            logger.debug("Registered tool '{}' from '{}'", tool.name, source)
        except Exception:
            exc_type, exc_value, exc_traceback = sys.exc_info()
            error_message = repr(traceback.format_exception(exc_type, exc_value, exc_traceback))
            logger.error("Failed to register tool '{}': {}", tool.name, error_message)
            raise

    def deregister(self, tool_name: str, allow_builtin: bool = False) -> None:
        """Remove a tool. Built-in tools cannot be removed unless allow_builtin=True."""
        if tool_name not in self._tools:
            logger.warning("Tool '{}' not found, nothing to deregister", tool_name)
            return

        if self._source_map.get(tool_name) == "builtin" and not allow_builtin:
            raise ValueError(f"Cannot deregister built-in tool '{tool_name}'")

        del self._tools[tool_name]
        del self._source_map[tool_name]
        logger.debug("Deregistered tool '{}'", tool_name)

    def deregister_skill_tools(self, skill_name: str) -> None:
        """Remove all tools registered by a specific skill."""
        source_key = f"skill:{skill_name}"
        to_remove = [name for name, src in self._source_map.items() if src == source_key]
        for name in to_remove:
            self.deregister(name)

    def get_tools(self) -> list[BaseTool]:
        return list(self._tools.values())

    def get_tool(self, name: str) -> Any:
        return self._tools.get(name)

    def list_tools(self) -> list[dict[str, str]]:
        return [
            {"name": name, "source": self._source_map[name], "description": t.description[:80]}
            for name, t in self._tools.items()
        ]

    def __contains__(self, name: str) -> bool:
        return name in self._tools

