"""
pi_agent/extensions/todos_extension.py

/todos extension — persistent to-do list for the agent session.

Inspired by Armin Ronacher's /todos extension for Pi.

To-dos are stored as individual Markdown files in .pi/todos/.
Both the agent (via bash) and the user (via /todos) can manipulate them.
Sessions can "claim" a to-do to mark it in progress.

Commands:
    /todos                   List all to-dos
    /todos add <text>        Add a new to-do
    /todos done <id>         Mark to-do as done
    /todos claim <id>        Mark to-do as in-progress (claimed by current session)
    /todos clear             Remove all completed to-dos
"""

from __future__ import annotations

import sys
import traceback
import uuid
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path
from typing import TYPE_CHECKING, Optional

from loguru import logger

if TYPE_CHECKING:
    from ..extensions.loader import ExtensionAPI


@dataclass
class Todo:
    id: str
    text: str
    status: str          # "pending" | "in_progress" | "done"
    created_at: str
    session_id: Optional[str] = None  # which session claimed it

    def to_markdown(self) -> str:
        status_icon = {"pending": "⬜", "in_progress": "🔄", "done": "✅"}.get(self.status, "⬜")
        claim = f"\n*claimed by session: {self.session_id}*" if self.session_id else ""
        return f"{status_icon} **{self.id[:6]}** {self.text}\n*created: {self.created_at}*{claim}"

    @classmethod
    def from_file(cls, path: Path) -> Optional["Todo"]:
        try:
            lines = path.read_text(encoding="utf-8").strip().splitlines()
            # Format: first line = status, second = text, third = created_at, optional fourth = session_id
            if len(lines) < 3:
                return None
            return cls(
                id=path.stem,
                status=lines[0].strip(),
                text=lines[1].strip(),
                created_at=lines[2].strip(),
                session_id=lines[3].strip() if len(lines) > 3 else None,
            )
        except Exception:
            exc_type, exc_value, exc_tb = sys.exc_info()
            error_message = repr(traceback.format_exception(exc_type, exc_value, exc_tb))
            logger.warning("Failed to parse todo file {}: {}", path, error_message)
            return None

    def save(self, todos_dir: Path) -> None:
        path = todos_dir / f"{self.id}.md"
        lines = [self.status, self.text, self.created_at]
        if self.session_id:
            lines.append(self.session_id)
        path.write_text("\n".join(lines), encoding="utf-8")


class TodosExtension:
    """
    /todos extension — session-aware persistent to-do list.
    """

    name = "todos"
    description = "Persistent to-do list stored in .pi/todos/"

    def __init__(self) -> None:
        self._todos_dir: Optional[Path] = None

    def register(self, api: "ExtensionAPI") -> None:
        # Determine todos directory relative to cwd
        self._todos_dir = Path(".pi") / "todos"
        self._todos_dir.mkdir(parents=True, exist_ok=True)

        api.add_command("todos", self.handle_todos)
        logger.debug("TodosExtension registered: todos_dir={}", self._todos_dir)

    @property
    def todos_dir(self) -> Path:
        d = self._todos_dir or Path(".pi/todos")
        d.mkdir(parents=True, exist_ok=True)
        return d

    def handle_todos(self, args: str) -> str:
        """Handle /todos [subcommand] [args]"""
        try:
            parts = args.strip().split(maxsplit=1)
            subcmd = parts[0].lower() if parts else ""
            rest = parts[1] if len(parts) > 1 else ""

            if subcmd == "add":
                return self._add(rest)
            elif subcmd == "done":
                return self._mark(rest, "done")
            elif subcmd == "claim":
                return self._mark(rest, "in_progress")
            elif subcmd == "clear":
                return self._clear()
            else:
                return self._list()

        except Exception:
            exc_type, exc_value, exc_tb = sys.exc_info()
            error_message = repr(traceback.format_exception(exc_type, exc_value, exc_tb))
            logger.error("TodosExtension.handle_todos failed: {}", error_message)
            return f"Error: {error_message}"

    def _list(self) -> str:
        todos = self._load_all()
        if not todos:
            return "No to-dos. Use `/todos add <text>` to add one."

        sections: dict[str, list[str]] = {"in_progress": [], "pending": [], "done": []}
        for todo in todos:
            sections.get(todo.status, sections["pending"]).append(todo.to_markdown())

        lines = ["## To-Do List\n"]
        if sections["in_progress"]:
            lines.append("### 🔄 In Progress\n")
            lines.extend(sections["in_progress"])
            lines.append("")
        if sections["pending"]:
            lines.append("### ⬜ Pending\n")
            lines.extend(sections["pending"])
            lines.append("")
        if sections["done"]:
            lines.append("### ✅ Done\n")
            lines.extend(sections["done"])
        return "\n".join(lines)

    def _add(self, text: str) -> str:
        if not text.strip():
            return "Usage: /todos add <text>"
        todo_id = str(uuid.uuid4())
        todo = Todo(
            id=todo_id,
            text=text.strip(),
            status="pending",
            created_at=datetime.now().strftime("%Y-%m-%d %H:%M"),
        )
        todo.save(self.todos_dir)
        logger.info("Todo added: {} - {}", todo_id[:6], text[:60])
        return f"✅ Added: [{todo_id[:6]}] {text}"

    def _mark(self, todo_id_prefix: str, status: str) -> str:
        todo = self._find(todo_id_prefix)
        if not todo:
            return f"To-do not found: {todo_id_prefix}"
        todo.status = status
        todo.save(self.todos_dir)
        icon = "🔄" if status == "in_progress" else "✅"
        logger.info("Todo {} marked {}: {}", todo.id[:6], status, todo.text[:60])
        return f"{icon} [{todo.id[:6]}] {todo.text} → {status}"

    def _clear(self) -> str:
        todos = self._load_all()
        removed = 0
        for todo in todos:
            if todo.status == "done":
                (self.todos_dir / f"{todo.id}.md").unlink(missing_ok=True)
                removed += 1
        return f"Cleared {removed} completed to-do(s)."

    def _load_all(self) -> list[Todo]:
        todos = []
        for path in sorted(self.todos_dir.glob("*.md")):
            todo = Todo.from_file(path)
            if todo:
                todos.append(todo)
        return todos

    def _find(self, prefix: str) -> Optional[Todo]:
        for path in self.todos_dir.glob("*.md"):
            if path.stem.startswith(prefix):
                return Todo.from_file(path)
        return None


# Extension singleton — ExtensionLoader looks for EXTENSION
EXTENSION = TodosExtension()

