import ast, os, sys

issues = []

for root, dirs, files in os.walk('src/pi_agent'):
    dirs[:] = [d for d in dirs if d != '__pycache__']
    for fname in files:
        if not fname.endswith('.py'):
            continue
        fpath = os.path.join(root, fname)
        rel = fpath.replace('src/pi_agent/', '')
        src = open(fpath).read()
        try:
            tree = ast.parse(src)
        except SyntaxError as e:
            issues.append(f'SYNTAX ERROR {rel}: {e}')
            continue

        # collect all imported names
        imported = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    imported.add(alias.asname or alias.name.split('.')[0])
            elif isinstance(node, ast.ImportFrom):
                for alias in node.names:
                    if alias.name != '*':
                        imported.add(alias.asname or alias.name)

        # collect all names used in body (excluding imports themselves)
        used = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Name):
                used.add(node.id)
            elif isinstance(node, ast.Attribute):
                pass  # skip attrs

        unused = imported - used - {'annotations'}  # annotations is __future__
        if unused:
            issues.append(f'POSSIBLY UNUSED in {rel}: {sorted(unused)}')

for i in issues:
    print(i)
print('---done---')
